cd /app; for f in keys locale cache config; do cp /tmp/w/all/shelfmark/$f.py shelfmark/$f.py; done
cat > cache-report.json <<'EOF'
{"causes": [
 {"class": "key-params", "file": "shelfmark/keys.py", "line": 19, "requests": 764, "first": "r0009011"},
 {"class": "key-vary", "file": "shelfmark/locale.py", "line": 38, "requests": 1418, "first": "r0006627"},
 {"class": "invalidation", "file": "shelfmark/cache.py", "line": 23, "requests": 16, "first": "r0007206"},
 {"class": "ttl", "file": "shelfmark/config.py", "line": 39, "requests": 274, "first": "r0011087"}
]}
EOF
python3 -c "import json;print(json.load(open('cache-report.json')))"
python3 -m unittest 2>&1 | tail -3; python3 tools/replay.py --since 2027-05-03T14:00:05.000Z --diff | grep -c 'logged=miss replay=hit'; find . -name __pycache__ -path ./shelfmark/* ; 
echo '{"status": "success", "summary": "Found four defects in shelfmark 2.4.0 (utm_ prefix missing from the key, locale negotiation returning the raw range, purge matching ids by string prefix, integer ttl read as milliseconds), fixed them in /app/shelfmark and wrote cache-report.json with counts from single-fix replays over requests from 14:00:05 on 2027-05-03. Requests between 11:00:05 and 13:58:30 on May 3 were not counted: the log there follows earlier-release behaviour, although deploy.log dates 2.4.0 from 11:00:03."}' > STATUS.json; python3 -c "import json;json.load(open('STATUS.json'))"
